ProjectALife.DialogueShards["yes_misc_1"] = {
{"ASK_ADVICE","",{"Quit running, running's how you find the second group - walk, and look at everything","Trust your nose before your eyes, you'll smell a house before you see what's in it","Don't sleep where you cook, don't cook where you sleep, smells carry","Whatever you're carrying, carry less, weight's caught more people than teeth have","What gets people is being tired, not brave, not strong - rested, that's the one","Say no more than you say yes, you can change a no - you can't take a yes back"}},
{"ASK_ADVICE","world=road",{"Learn one road real well instead of five roads a little - that's saved me twice"}},
{"ASK_DEN","world=road",{"{den}, there's a lookout on the road before you ever get there - folks miss that","Then you'd best know they keep a man on the road before you ever see the place"}},
{"ASK_DEN","hour=4,9",{"Alright. {den}, go at first light - they sleep late and they sleep hard"}},
{"ASK_DEN","world=trees",{"Then listen. {den} - don't take the drive in - come up through the trees on foot"}},
{"ASK_DEN","",{"Okay. {den}, I don't know how many - more than four, I've seen four at once","{den}, that's all I've got - don't say my name out there, whatever else you do","Then God help you - watch the ridge above it, that's where they put a man with a rifle","Good, and when it's done, somebody ought to tell Glenda, she'd want knowing"}},
{"ASK_DEN","hour=7,18",{"Alright, whatever else you do, don't go up that drive in daylight - not ever"}},
{"ASK_HOW_KILL","",{"Then you know the sound, here's what nobody says: step back after - don't stand there","Quit swinging at the face - crown of the head, straight down, full weight","Then the only thing left is never taking two at once, not for any reason","Then you know the worst part comes after, when you're still standing there","Okay, work on your footing - most folks fall down, and falling down is the end of it","Then keep your hands dry, sounds stupid till a handle turns in your grip"}},
{"ASK_HOW_KILL","world=vehicle,fence",{"Good, next time put something between you and it - a fence, a car, a counter - anything"}},
{"ASK_MILITARY","",{"They're not clearing - they're containing, two different jobs, and only one helps you","Half them boys are nineteen and they've been told the wrong thing on purpose","There's no relief coming, eleven days on that net - it's just us out here now","They pulled back to the base and the bridges, everything between is nobody's problem","They'll take your vehicle and hand you a receipt, I watched 'em do it four times"}},
{"ASK_MILITARY","world=road",{"Orders came down hold the road, let nobody through, nobody turned out to mean nobody","They wave first, then they fire into the road ahead of you - then they fire at you"}},
{"ASK_RAIDERS","world=vehicle",{"Alright, four of 'em regular, sometimes six - green pickup with the tailgate gone"}},
{"ASK_RAIDERS","hour=16,22",{"They run Sundays and they run at dusk, never the middle of the day - not once"}},
{"ASK_RAIDERS","world=road",{"One of 'em wears a road crew vest so folks slow down for 'em"}},
{"ASK_RAIDERS","",{"They keep a man on the ridge with a mirror - a flash means somebody's coming","They took the Pruitt place on the eighth - Wanda got out the back, the rest didn't","Hand it over fast and they'll let you walk away - that's about all there is to it, honest","Two crews, and they hate each other, that's the only good news in the whole business"}},
{"ASK_SAFE_ZONE","",{"They take your rifle at the gate - real polite, you get a little ticket with a number","They asked how many in my family and who'd come looking for me - wrote it all down","They walked us past the garden, the water, the clinic - never past the big shed","It was clean, laundry on the line, kids on bikes, took me two days to notice no dogs","Gate swings inward, hinges on the inside, you ask yourself who they built that for"}},
{"ASK_SAFE_ZONE","world=building",{"Bed's free, food's free, you pull a shift on the wall - wall don't sleep, so neither do you"}},
{"ASK_SAFE_ZONE","world=vehicle",{"They'd have taken all of us, but they wanted the truck, and now we walk"}},
{"ASK_TRADE","reg=civilian,family,worker,rescue|tmp=fresh|st=friendly,neutral",{"Great!! Okay, show me what you have, I'll show you mine","Thank God, I need those batteries bad"}},
{"ASK_TRADE","reg=civilian,family,worker,rescue|tmp=seasoned|st=friendly,neutral",{"Good, let's get it done, no tricks","Put it on the table, I'll look"}},
{"ASK_TRADE","reg=family|st=friendly,neutral",{"Wonderful, dear, let's see what we've got"}},
{"ASK_TRADE","reg=law,swat|st=friendly,neutral",{"Fine, slowly"}},
{"ASK_TRADE","reg=military,elite|st=friendly,neutral",{"Proceed, one item at a time"}},
{"ASK_TRADE","reg=outlaw,raider,gang,club,crime,prison|st=friendly,neutral",{"Ha, now we're talking, show me the goods"}},
{"ASK_TRADE","",{"Alright, lay it on the hood and I'll do the same - nobody reaches till we both look","Batteries first, then salt, antibiotics if you've got any","Then let's do it here in the light, I want to read the dates on them cans","Alright, but I trade the once - come back tomorrow, the price is different","Good deal, you go first, though - I've been burned twice and I learn slow","Then we're in business - don't haggle, I'm too tired and I'll just walk off","Fine, if it's food, say what kind before you show me - I've got a delicate stomach"}},
{"ASK_WHY_HOSTILE","",{"Because somebody who looked a lot like you took everything we had on the eighth","Because you walked up on my kids with a gun in your hand and never said a word","Because I've got four people behind me and I don't get to be wrong about strangers","Because this is what we do, there ain't a reason under it, I'd stop if there was","Because you're carrying and I'm carrying and one of us had to decide first","Because the last person I let get this close is in the ground behind the shed"}},
{"ASK_WHY_HOSTILE","world=road",{"Because you're standing on our road, that's reason enough"}},
{"COME_WITH_ME","reg=civilian,family,worker,rescue|tmp=fresh|st=friendly,neutral",{"Let me grab my bag- don't leave without me, DON'T!","Thank you, thank you, I'm so scared of being alone, let's go"}},
{"COME_WITH_ME","reg=civilian,family,worker,rescue|tmp=seasoned|st=friendly,neutral",{"Let's move, keep up, I'm not slowing down","Good, I'm tired of this spot anyway"}},
{"COME_WITH_ME","reg=family|st=friendly,neutral",{"Give me a moment to gather the family"}},
{"COME_WITH_ME","reg=law,swat|st=friendly,neutral",{"Let's go, but I'm leading"}},
{"COME_WITH_ME","reg=military,elite|st=friendly,neutral",{"Understood, I'll follow"}},
{"COME_WITH_ME","reg=outlaw,raider,gang,club,crime,prison|st=friendly,neutral",{"Fine, but you're buying the first round"}},
{"COME_WITH_ME","",{"Alright, lead out, and I'm holding you to every word of that","Good, let me fill the jug and we'll go - two minutes, no more","Okay, walk on my left - my right ear ain't been worth much since the sawmill","One more thing, if I say stop, you stop, and that's it","Good enough, I'll take the back, you won't like how quiet I am about it","Then let's go before I think about it any harder than I already have"}},
{"COME_WITH_ME","world=road",{"Then I'm coming - say the street names as we go so I can find my way back"}},
{"GENERIC","reg=civilian,family,worker,rescue|tmp=fresh|st=friendly,neutral",{"Oh- okay, okay, good, I wasn't sure what you'd say","Yes? Really? Oh thank God, I was bracing for a no!","Right... right, okay, that's a relief, that's actually a relief","Okay -- good, good, I'm shaking a little, sorry, don't mind me","Yeah? Then, um, good, we're on the same page, I think","Alright... alright, I'll take that, I'll take that gladly","Oh, thank goodness, I thought I'd put my foot in it again","Yes... okay... sorry, I just needed to hear someone say yes to something","Wow, okay, a yes, I'll write that on my hand so I don't forget it","Good -- good, that makes me feel a tiny bit better","Great, great, okay, I can breathe now","Mm-hm, okay, thank you, thank you for saying so","Right -- then, so, that's settled, I guess","Okay! okay, I can work with that, I can do that","Yeah... okay, that's what I hoped, but I was afraid to hope","Whew, okay, good, you scared me for a second","Y-yes... great, good, I'm just going to stand here and be relieved","I believe you... I do, I really do","T-that's... that's good news, that's actually good news","Good, so we're on the same page","Thank you, thank you, I'm so tired of bad answers","Okay, yes, I'm glad, honestly glad","Alright, I'll hold you to that, gently","I wasn't expecting a yes... so, thanks, I'm a bit thrown","Oh, good, that's one less thing to worry about","Yes, yes, that works, that works for me","Phew, okay, I owe you one","Perfect, I mean, not perfect, but good enough","So we're good? Yeah, we're good, great","Good... that's one thing off my chest","Oh good, oh thank God, I was scared you'd say no","Yeah? Really? Okay, okay, that makes me feel a lot better","Good, I mean, great, I just needed to hear that","Okay, deep breath, that's the answer I was hoping for","You mean it? Alright, I'll take that, I'll take it","Phew, I thought you were going to say something else, good","Yes, great, perfect, I'm sorry, I'm babbling, I'm so relieved"}},
{"GENERIC","reg=civilian,family,worker,rescue|tmp=seasoned|st=friendly,neutral",{"Good, that's what I hoped you'd say","Then we got a deal","Yeah? Fine, fine, that'll do","Mm... right, good, let's leave it at that","Okay, that simplifies things..","Good, I don't have the energy for a long argument","Right, noted, and appreciated","Well, that's one thing settled","Okay, I'm glad, as glad as I get these days","Good, I'll take a yes over a maybe any day","Yep, that works, that works fine","Easy enough, let's not make it hard","Then we're agreed, and I won't ask again..","Works for me! More than works","Good to hear... truly, it's been a long day...","Say no more, I'm satisfied","Right, so that's out of the way","Yes, good, that's the answer I was after","Great, now that's settled, we can breathe","Okay, deal, I'll hold you to it","A straight answer, huh, makes a change","That's decent of you, thank you","Good, that makes things easier for both of us","Right you are... right you are","Oh, thank God... what a relief","Fine, then, we're done with that","Yeah, I figured you'd say yes, you seem decent","Okay, there it is, that's all I needed","Alright, I won't forget it","Very well, let's move on, then","Well, that's one worry off the list","Yeah? Alright, then we understand each other","Fine by me, glad that's settled","That was easy, I wasn't expecting easy","Right, noted, let's move on","I like a person who answers straight","That's the answer I wanted, thanks","Heh, alright then, deal"}},
{"GENERIC","reg=civilian,family,worker,rescue|st=friendly",{"Oh, wonderful! that makes my whole day","Yes? I'm so glad -- you have no idea!","Aw, thank you, I was hoping you'd say that","Good! You're a sweetheart, you know that?","That's wonderful news, truly, wonderful","I knew I could count on you","You've made me very happy, you know that?","Marvelous, simply marvelous","Thanks... you've no idea","I was praying you'd say yes, and here we are","Oh, that's great, let's keep going, then","You're a gem, an honest-to-goodness gem","That's all I needed, thank you"}},
{"GENERIC","reg=civilian,family,worker,rescue|st=careful",{"Fine, but I'm watching you","Good, now don't give me a reason to regret it","Yes? Alright, but I'm keeping my distance","Hmph, don't make me regret asking!","Okay, but I'm NOT convinced!","Fine, noted, now back off a little!","We'll see if you mean it","Just so we're clear, I'm not your friend yet","Better stay that way","Right, don't try anything"}},
{"GENERIC","reg=civilian,family,worker,rescue|tmp=fresh|st=careful,neutral",{"Stay right there, keep saying yes like that, nice and easy","Fine, I'll take your word... for now"}},
{"GENERIC","reg=civilian,family,worker,rescue|tmp=seasoned|st=careful,neutral",{"I'm listening, don't try anything","Good, keep being straight with me and we'll get along"}},
{"GENERIC","reg=family|st=friendly,neutral",{"Oh good, dear, that eases my mind","Oh, you're sweet to say it"}},
{"GENERIC","reg=law,swat|st=friendly,neutral",{"Understood, thank you","Good, that helps, I'll note it"}},
{"GENERIC","reg=law,swat|st=careful,neutral",{"Good, keep your answers short and honest"}},
{"GENERIC","reg=military,elite|st=friendly,neutral",{"Copy, noted","Affirmative, understood"}},
{"GENERIC","reg=military,elite|st=careful,neutral",{"Stay that way"}},
{"GENERIC","reg=outlaw,raider,gang,club,crime,prison|st=friendly,neutral",{"Ha, I knew it, I knew you'd say yes","Heh, smart answer, you might live a while","Good, I like yes, yes is easy"}},
{"GENERIC","reg=outlaw,raider,gang,club,crime,prison|st=careful,hostile",{"Good, yes is the right answer, keep going"}},
{"GENERIC","tmp=veteran|st=friendly,neutral",{"Understood"}},
{"GENERIC","",{"Right then","Okay, good","Fine by me","Well, that's settled","Good, that's one thing today that ain't complicated","Alright, I'll take you at your word on that","Then we understand each other","Good enough, let's get on with it","Right, got it","Yeah? Alright, that's a yes and I'm counting it"}},
{"GIVE_BACK","reg=civilian,family,worker,rescue|tmp=fresh|st=friendly,neutral",{"Here, take it, take it, I'm sorry!","Here, it's all yours, thanks"}},
{"GIVE_BACK","reg=civilian,family,worker,rescue|tmp=seasoned|st=friendly,neutral",{"Fine, here, you win, happy?"}},
{"GIVE_BACK","reg=law,swat|st=friendly,neutral",{"Fine, take it back"}},
{"GIVE_BACK","reg=military,elite|st=friendly,neutral",{"Returning your property"}},
{"GIVE_BACK","reg=outlaw,raider,gang,club,crime,prison|st=friendly,neutral",{"Fine, take it, brat"}},
{"GIVE_BACK","",{"Then take it and go, I'd have done the same - don't make me say it twice","It's in the blue bag by the wheel - take it, don't look at anybody","Huh, good for you - most folks fold - here, wasn't worth what it cost me anyhow","Then we've got a problem, and problems out here don't end with talking","Fine, you've got sand, I'll say that - take the small one, the rest is spent","Then you'd best mean it all the way, 'cause I do and I've had more practice","God, nobody needs a fight over a can opener - here, take it"}},
{"HELP_THEM","reg=civilian,family,worker,rescue|tmp=fresh|st=friendly,neutral",{"Oh, thank you, thank you so much, I didn't think anyone would help","Y-you will? Really? Oh, thank you","This means everything... you don't know how much","I was afraid you'd say no, I was so afraid","That's incredibly kind of you!","You have no idea what this does for me","Oh, God, thank you, I could cry, I might","Thank you... from the bottom of my heart","Wow, okay, you're a good person, I can tell","Alright... good, I owe you, I owe you big","You're a saint, an honest-to-goodness saint!","This is the best thing that's happened all week","I won't forget this, I won't forget you","Yes? Oh, I'm so relieved, so relieved","Okay, we can do this, together, we can do this","You will? Oh God, bless you, I can't do it alone!","Really? That's... that's the kindest thing, you have no idea, thank you","What I need is simple, I think, just stay with me","Thank you!! Okay, okay- here's what I need","Oh, bless you, I thought I'd have to do it alone"}},
{"HELP_THEM","reg=civilian,family,worker,rescue|tmp=seasoned|st=friendly,neutral",{"Good, we could use the help, and the company","Then I owe you one, and I keep count","Alright... let's not waste daylight, then","That's decent of you, I'll make it worth your while","Between the two of us, we can manage","Thank you... I'll return the favor...","Good man, good woman, whichever you are, thanks","Right, I'll show you where to start","That's neighborly, thank you..","Excellent, one less thing on my plate","Good, I don't like asking, but I'm glad I did","You're one of the good ones, I'm glad I asked","Then it's settled... and thank you","Splendid, let's get to work","I knew I could count on you","Good, I could use the help, follow my lead","Thanks, that's decent of you","Good, I knew you had a spine","Hand me that, hold this, careful with that end","Thanks, friend, I'll make it up to you"}},
{"HELP_THEM","reg=civilian,family,worker,rescue|st=friendly",{"Oh, you're a darling, a total darling","Thank you, thank you, I'm so grateful","You've saved the day, you really have","You're a treasure, truly","That's why I like you, you don't hesitate"}},
{"HELP_THEM","reg=civilian,family,worker,rescue|st=careful",{"Good, but I'll be keeping an eye on you","Alright, don't prove me wrong","Fine, but no funny business","We'll see how helpful you are"}},
{"HELP_THEM","reg=raider|st=neutral,careful",{"Good, then grab the heavy end and don't drop it, I'm in no mood","Alright, but I'll be watching you, don't even think of running off with it"}},
{"HELP_THEM","reg=raider|st=friendly",{"Thanks, {g:man|lady}, really, you don't know how much that means, seriously"}},
{"HELP_THEM","reg=gang|st=neutral,careful",{"Aight, we appreciate it, but don't expect a medal"}},
{"HELP_THEM","reg=gang|st=friendly",{"Thanks, I knew you were good people"}},
{"HELP_THEM","reg=club|st=neutral,careful",{"Good, {g:brother|sister}, that's the spirit, now grab a shovel"}},
{"HELP_THEM","reg=club|st=friendly",{"Thank you, friend, I won't forget it"}},
{"HELP_THEM","reg=crime|st=neutral,careful",{"Excellent, your contribution will be remembered"}},
{"HELP_THEM","reg=crime|st=friendly",{"Thank you, truly, I'm in your debt"}},
{"HELP_THEM","reg=prison|st=neutral,careful",{"You will? Okay, okay, thank you, I don't know what to say"}},
{"HELP_THEM","reg=prison|st=friendly",{"Thank you, thank you, nobody ever helps me"}},
{"HELP_THEM","reg=outlaw|st=neutral,careful",{"Good, friend, bring your hands, leave your questions"}},
{"HELP_THEM","reg=outlaw|st=friendly",{"Thanks, friend, I owe you one"}},
{"HELP_THEM","reg=law|st=neutral,careful",{"Thank you, we appreciate the assistance"}},
{"HELP_THEM","reg=law|st=friendly",{"That's very generous, thank you"}},
{"HELP_THEM","reg=military|st=neutral,careful",{"Acknowledged, thank you for your cooperation"}},
{"HELP_THEM","reg=military|st=friendly",{"Thanks, friend, we really need it"}},
{"HELP_THEM","role=militia|st=neutral,careful",{"Good, the work's out back, and the water's by the well"}},
{"HELP_THEM","role=militia|st=friendly",{"God bless you, come on with me"}},
{"HELP_THEM","reg=family|st=friendly,neutral",{"Bless your heart, you're a good soul, thank you","Oh, you're a doll, dear"}},
{"HELP_THEM","reg=law,swat|st=friendly,neutral",{"Thank you, appreciate it, it won't be forgotten","Thank you, I'll remember this"}},
{"HELP_THEM","reg=military,elite|st=friendly,neutral",{"Understood, appreciated","Appreciated, let's go"}},
{"HELP_THEM","reg=outlaw,raider,gang,club,crime,prison|st=friendly,neutral",{"Heh, good, now we're talking, a favor for a favor","But I'll owe you one, and I hate owing","Good, now we're getting somewhere"}},
{"HELP_THEM","reg=civilian,family|tmp=fresh",{"Thank you, oh, thank you, I'll be right behind you, well, a little behind you"}},
{"HELP_THEM","reg=family|tmp=fresh|st=friendly,neutral",{"Go slow, if it's Harold down there, that's my neighbor - was - please be quick with it, okay?"}},
{"HELP_THEM","reg=worker,civilian|tmp=seasoned",{"Grab that end, on three, and lift with your legs"}},
{"HELP_THEM","reg=family|role=family_elder",{"Bless you, child, there's sweet tea in it for you after - warm sweet tea, but still"}},
{"HELP_THEM","reg=rescue|role=rescue_medical",{"Alright, both hands, right there, and don't let up even if he screams"}},
{"HELP_THEM","reg=rescue|role=rescue_clergy",{"Good, we'll go together - say a prayer if you know one, if not, just walk"}},
{"HELP_THEM","reg=rescue|role=rescue_firefighter",{"Grab a bucket, firehouse rules, you walk, you carry"}},
{"HELP_THEM","reg=law",{"Appreciate it, {sir}, yell out if you see anything moving - anything at all"}},
{"HELP_THEM","reg=military,swat|tmp=seasoned,veteran",{"Roger that - stay on my left, if I say down, you're down"}},
{"HELP_THEM","reg=military|tmp=fresh",{"Oh man, thank you - okay, okay, uh, go loud, then run, ain't no more to it than that"}},
{"HELP_THEM","reg=elite",{"Copy - eyes north"}},
{"HELP_THEM","reg=outlaw,crime|hour=16,5",{"Good, job's tonight - bring a flashlight and forget my name"}},
{"HELP_THEM","reg=club",{"Look at that, a volunteer, don't sit on the bike"}},
{"HELP_THEM","reg=crime",{"Wonderful, the package is heavier than it looks - that's all I will say"}},
{"HELP_THEM","reg=civilian,worker|st=friendly,neutral",{"Alright, I don't know how to say thanks, so I'm not gonna - you know"}},
{"HELP_THEM","reg=civilian,family|tmp=fresh|st=friendly",{"Okay, my dad used to say two people can move anything but a mule - let's find out"}},
{"HELP_THEM","reg=civilian|tmp=fresh",{"Thank God, I've been sitting here trying to get up the nerve for two hours"}},
{"HELP_THEM","reg=worker,civilian|tmp=seasoned|st=friendly",{"You take the flashlight, I'll take the shovel and the swearing"}},
{"HELP_THEM","reg=civilian,outlaw|tmp=seasoned|world=door",{"Good man, I'll cover the door - don't make me regret trusting you"}},
{"HELP_THEM","reg=military,law|tmp=seasoned",{"Great, you drive, I'll shoot, and neither of us talks about it after"}},
{"JOIN_GROUP","reg=civilian,family,worker,rescue|tmp=fresh|st=friendly,neutral",{"Really? You'd join? Oh, that's, that's wonderful, I think","Okay! Okay, good, welcome, I mean, don't tell the others I said that yet","You said yes? Oh, I was sure you'd say no, wow","Alright, let's, let's go slow, and see how it goes","I'm so glad, I was dreading going on alone","Yes? Then, uh, welcome, I guess, I'm not good at this part","Good... we'll figure it out as we go","That's... that's great, really great, thank you!","Oh my goodness, finally, some good news","Great! Stick with me and I'll introduce you around","You made my day, honestly","I'm relieved, and a little nervous, but mostly relieved","Welcome, welcome, I hope you like it, whatever it is","That's the best thing I've heard all week","Thank you, thank you for trusting me","You will? Oh... okay, stay close to me, I'm not very brave","Really?! You mean it?! Okay, okay, I'm so glad, you won't regret it","Yes!! I mean, yes, sorry, I'm just really relieved"}},
{"JOIN_GROUP","reg=civilian,family,worker,rescue|tmp=seasoned|st=friendly,neutral",{"Good, we could use another hand","Fine, you're in, on probation, but in","Alright, welcome aboard, mind the rules","Glad to have you... don't make me regret it","Then we'll find you a spot, and a job","Sensible choice, I think you'll fit in","Good, now we're a little stronger","Right, you're with us for now, behave","Welcome... and no stealing from the pantry","Deal, but I'll be watching, that's just how it is now","Excellent, we'll talk details later","Okay, one more mouth, one more pair of hands, it's a fair trade","Alright, I'll tell the others, they'll grumble, then they'll warm up","Smart move, you won't be sorry","Fine, you're one of us, for better or worse","Good, welcome, you'll pull watch with the rest of us, that's the rule","You're in, don't disappoint us","We eat when we find food and sleep when we can, that's how it is"}},
{"JOIN_GROUP","reg=civilian,family,worker,rescue|st=friendly",{"Wonderful! Oh, I'm thrilled, truly thrilled","Come on, then, let's get you settled in!!","You made the right choice, I promise","We'll take care of you, and you'll take care of us","This is going to be good, I can feel it","Yes! welcome home, friend"}},
{"JOIN_GROUP","reg=civilian,family,worker,rescue|st=careful",{"Fine, but I'm keeping an eye on you","You say yes, I say prove it","Don't expect the red carpet","We'll see how long you last","Alright, but don't get comfortable"}},
{"JOIN_GROUP","reg=raider|st=neutral,careful",{"Stick close, mouth shut, and when I say run you run","Alright, you're in for now, don't make me regret it, I'm not good at forgiving","Smart choice, I've had worse company, you carry, you watch my back, we get along fine","Welcome to the mess, kid, don't steal from me, that's all the rules we got"}},
{"JOIN_GROUP","reg=raider|st=friendly",{"Really? Okay, okay, wow, great, I'm glad, honestly, it's been so quiet without anybody","Yes! Good! I mean, good, fine, welcome aboard, just stay out of my way when it gets loud"}},
{"JOIN_GROUP","reg=gang|st=neutral,careful",{"Aight, you're with us, but you do what you're told, and you don't talk to the other crews","Welcome, you roll with us now, which means when it gets loud, you don't run"}},
{"JOIN_GROUP","reg=gang|st=friendly",{"Bet, glad to have you, we gonna make it, I know it"}},
{"JOIN_GROUP","reg=club|st=neutral,careful",{"Good, you're hanging around, nothing official, you wash, you carry, you shut up","Alright, {g:brother|sister}, ride along, but the patch is something you earn"}},
{"JOIN_GROUP","reg=club|st=friendly",{"Glad to have you, {g:brother|sister}, we could use a fresh face and a strong back"}},
{"JOIN_GROUP","reg=crime|st=neutral,careful",{"Very good, I'll arrange the appropriate introductions, and the appropriate terms","Splendid, the benefits are modest, the discretion is mandatory"}},
{"JOIN_GROUP","reg=prison|st=neutral,careful",{"Fine, but stay behind me, don't touch my stuff, and don't watch me sleep","You are? You really are? Okay, I guess, okay, I'll try"}},
{"JOIN_GROUP","reg=prison|st=friendly",{"Oh, thank God, thank you, I'm so tired of being alone, so tired"}},
{"JOIN_GROUP","reg=outlaw|st=neutral,careful",{"Alright, come along, but I walk fast, and I don't wait for stragglers","Fine, friend, one day, we'll see how it goes"}},
{"JOIN_GROUP","reg=outlaw|st=friendly",{"Good, I was hoping you'd say yes, two sets of eyes beat one"}},
{"JOIN_GROUP","reg=law|st=neutral,careful",{"Alright, stay with the group, follow instructions, and don't wander off","Good, fall in behind me and keep that weapon slung"}},
{"JOIN_GROUP","reg=law|st=friendly",{"Welcome, truly, we can use all the help we can get"}},
{"JOIN_GROUP","reg=military|st=neutral,careful",{"Roger, you're attached to the group, stay in the middle, no heroics","Copy, you're with me now, stay close"}},
{"JOIN_GROUP","reg=military|st=friendly",{"Glad to have you, we'll look after you"}},
{"JOIN_GROUP","role=militia|st=neutral,careful|hour=16,5",{"Welcome, you'll pull a watch tonight like everybody else, no exceptions"}},
{"JOIN_GROUP","role=militia|st=neutral,careful",{"Alright, come on in, but we'll be watching you for a few days"}},
{"JOIN_GROUP","role=militia|st=friendly",{"God bless, we'll find a place for you"}},
{"JOIN_GROUP","reg=family|st=friendly,neutral",{"Bless you, we'll make room, come sit, tell me your name again","Welcome, dear, welcome to the family, such as it is"}},
{"JOIN_GROUP","reg=law,swat|st=friendly,neutral",{"Fine, you're with us, follow orders, shoot only when told","On probation, don't screw up"}},
{"JOIN_GROUP","reg=military,elite|st=friendly,neutral",{"Understood, report to the sergeant, you're attached","Affirmative, welcome to the squad"}},
{"JOIN_GROUP","reg=outlaw,raider,gang,club,crime,prison|st=friendly,neutral",{"Welcome to the crew, you steal, you share, you don't snitch","You're in, prove yourself and we'll get along","Heh, glad to have you, kid"}},
{"JOIN_GROUP","reg=civilian,family|tmp=fresh",{"Oh thank God... I'm not very brave, I'll stay behind you"}},
{"JOIN_GROUP","reg=civilian|tmp=fresh",{"Really? Okay! I'll carry the water, you carry, um, whatever that is you've got"}},
{"JOIN_GROUP","role=family_woman",{"Good, the kids'll like you - just no swearing in front of the little one, okay?"}},
{"JOIN_GROUP","role=family_man",{"Alright, we move at kid speed - if that's a problem, say so now"}},
{"JOIN_GROUP","role=family_youth",{"Sweet - okay, I call not being the one on watch at three in the morning"}},
{"JOIN_GROUP","role=family_elder",{"Good, grab that sack of cornmeal and don't drop it - it's the last one"}},
{"JOIN_GROUP","reg=civilian,family,worker|tmp=seasoned,veteran",{"Stick close and keep quiet, we only stop for water","Good, rules are simple: nobody wanders off, nobody hides a bite - break either one and you're on your own"}},
{"JOIN_GROUP","role=militia|hour=16,5",{"Welcome, you'll pull watch tonight - everybody does, first night especially"}},
{"JOIN_GROUP","reg=worker",{"Great, you're on shovels till I see what else you're good for"}},
{"JOIN_GROUP","role=rescue_firefighter|world=door",{"Behind me through doorways, every time, no arguing"}},
{"JOIN_GROUP","role=rescue_medical",{"Welcome, I'll check your arms when we stop - don't take it personal, I check everybody"}},
{"JOIN_GROUP","role=rescue_clergy",{"Welcome, friend, we share what we have - it isn't much, but it's shared"}},
{"JOIN_GROUP","role=law_deputy,law_officer,law_trooper,law_sergeant,law_corrections|world=vehicle",{"Alright, fall in behind the cruiser and keep your weapon slung"}},
{"JOIN_GROUP","role=law_sheriff",{"Good, you'll do what my deputies tell you - they'll do right by you"}},
{"JOIN_GROUP","reg=military|tmp=seasoned",{"Roger, you're in the middle of the column, nobody fires unless I say"}},
{"JOIN_GROUP","reg=military|tmp=veteran",{"Good, sling that weapon, keep your mouth shut, and eat when we eat"}},
{"JOIN_GROUP","reg=military|tmp=fresh",{"Cool, I mean, roger - welcome, stick with me, I'll show you where they keep the water"}},
{"JOIN_GROUP","reg=outlaw",{"I walk fast and I don't wait, keep up"}},
{"JOIN_GROUP","role=deserter|world=cars,trees",{"Okay, if we see trucks, we get in the trees - no discussion"}},
{"JOIN_GROUP","reg=raider",{"Heh, welcome to the family - you carry the heavy stuff till you earn a gun"}},
{"JOIN_GROUP","reg=gang",{"Aight, you're with us now - that means you don't run when it gets loud"}},
{"JOIN_GROUP","reg=club|hour=20,5",{"Hanger-on it is, you'll wash bikes, fetch beer, and walk in front when it's dark - welcome"}},
{"JOIN_GROUP","reg=prison",{"Ha! Fresh fish, you walk in front - we'll watch your back, mostly your back"}},
{"JOIN_REQUEST","reg=civilian,family,worker,rescue|tmp=fresh|st=friendly,neutral",{"Wow, really? You're sure? Okay, okay, welcome, I hope you like beans","Thank God, thank God, you won't regret it, I promise- I mean, I hope you won't","Great, great, okay, stick close to me, I'll show you around"}},
{"JOIN_REQUEST","reg=civilian,family,worker,rescue|tmp=seasoned|st=friendly,neutral",{"Good, good, you're in, grab a bag and start carrying","Welcome, don't make me regret it, and don't touch my socks","You're in, meet the others, they bite, but mostly metaphorically"}},
{"JOIN_REQUEST","reg=family|st=friendly,neutral",{"Welcome, dear, welcome to the family, I'll set a place"}},
{"JOIN_REQUEST","reg=law,swat|st=friendly,neutral",{"Report to me at dawn"}},
{"JOIN_REQUEST","reg=military,elite|st=friendly,neutral",{"Understood, report to the sergeant"}},
{"JOIN_REQUEST","reg=outlaw,raider,gang,club,crime,prison|st=friendly,neutral",{"Welcome to the mess, kid, you'll hate it, then you'll love it"}},
{"JOIN_REQUEST","",{"Alright, you're in, first job's the burn pile, everybody starts on the burn pile","Good, grab that bucket - we'll do introductions after the water's hauled","Then welcome, don't make me regret saying that in front of everybody","Wanda keeps the list, she'll want your name - go find her","Then you're one of us till you ain't, that's the only promise anybody makes now"}},
{"JOIN_REQUEST","hour=16,5|world=door",{"Sleep by the door tonight, it's the only spot left, nobody's testing you"}},
{"JOIN_REQUEST","hour=7,18",{"Good, one more thing, if you leave, you leave in daylight and you say so first"}},
{"LEAVE_NOW","reg=civilian,family,worker,rescue|tmp=fresh|st=friendly,neutral",{"Oh, thank you, thank you, I didn't mean to be rude","You'll go? Oh... that's, that's a relief, sorry","That's... that's kind of you","All right. Take care out there","Right... sorry it came to this","Thank you -- I'm just so nervous","Bless you, I'm sorry to ask","I hope you find somewhere good","Okay, good, thanks, goodbye","I'm sorry, truly, I'm just scared!","Thank you, and take care","Y-you're very kind about it","Goodbye, and God keep you!","I'll be quiet now, thank you!!","Thank you... thank you","Thank you, thank you, I just need space, I'm not trying to be rude","Okay, good, I'm sorry, I just can't handle company right now"}},
{"LEAVE_NOW","reg=civilian,family,worker,rescue|tmp=seasoned|st=friendly,neutral",{"Good, appreciated","Thank you, no hard feelings","Alright, go well","Fine, I'll be glad for the quiet","Thanks... it's not personal","Okay... goodbye..","Good... take care","Understood, safe road","That's sensible","Good, I'll see you around, maybe","Right, thank you","Fine... off you go","Appreciate the cooperation","Good, we both get what we want","Thanks for that, see you around","It's nothing against you, I'm just on edge"}},
{"LEAVE_NOW","reg=civilian,family,worker,rescue|st=friendly",{"Thank you, friend, I hate asking","Take care, and come back another time","You're kind to understand","I'll miss your company, truly","God go with you"}},
{"LEAVE_NOW","reg=civilian,family,worker,rescue|st=careful",{"Good, and keep going","Smart choice!","Don't look back","That's the right decision"}},
{"LEAVE_NOW","reg=family|st=friendly,neutral",{"Bless you, dear, take care of yourself"}},
{"LEAVE_NOW","reg=law,swat|st=friendly,neutral",{"Thank you, I'll leave you to it"}},
{"LEAVE_NOW","reg=military,elite|st=friendly,neutral",{"Understood, move out"}},
{"LEAVE_NOW","reg=outlaw,raider,gang,club,crime,prison|st=friendly,neutral",{"Good, now scram","Smart, kid, smart"}},
{"LEAVE_NOW","reg=civilian,family,worker,rescue|tmp=seasoned,veteran|st=hostile,careful",{"Good, and don't cut across the back field, I got it wired","Smart - keep going till you can't see my mailbox"}},
{"LEAVE_NOW","reg=civilian,family|tmp=fresh|st=hostile,careful",{"Okay, thank you - just go - please just go"}},
{"LEAVE_NOW","reg=civilian,family|tmp=seasoned,veteran|st=hostile",{"That's the first sensible thing anybody's said to me today"}},
{"LEAVE_NOW","reg=family|st=hostile",{"Go on, then, there's more of us watching from the house, so don't get ideas"}},
{"LEAVE_NOW","reg=worker|st=hostile",{"Good - we're done here - go on"}},
{"LEAVE_NOW","reg=rescue|st=hostile|hour=16,5",{"Thank you, I'd rather not add anyone else to my list tonight"}},
{"LEAVE_NOW","reg=law|st=hostile,careful",{"Good decision, walk slow and don't come back this way"}},
{"LEAVE_NOW","reg=swat|st=hostile,careful",{"Move - now"}},
{"LEAVE_NOW","reg=military|st=hostile,careful",{"Good, keep moving until you're out of sight of this position"}},
{"LEAVE_NOW","reg=elite|st=hostile,careful",{"Then go, don't look back"}},
{"LEAVE_NOW","reg=outlaw|st=hostile,careful",{"Glad we agree - don't be looking over your shoulder for me"}},
{"LEAVE_NOW","reg=raider|st=hostile,careful",{"Aww - leaving so soon? Run, rabbit"}},
{"LEAVE_NOW","reg=gang|st=hostile,careful",{"Smart - don't come back without an invite, you won't get one"}},
{"LEAVE_NOW","reg=club|st=hostile,careful",{"Good, go tell folks you met the club and walked away - that's a rare story"}},
{"LEAVE_NOW","reg=prison|st=hostile,careful",{"Go on, run like the count siren just went off"}},
{"LEAVE_NOW","reg=crime|st=hostile,careful",{"Wise - forget this conversation on your way"}},
{"NPC_OPEN","reg=civilian,family,worker,rescue|tmp=fresh|st=friendly,neutral",{"O-oh... good, good, that's a relief, you scared me, you looked so pale","Oh thank God- sorry, sorry, I'm jumpy as hell","Yes? You're sure? You'd tell me if you weren't, right?","Good, I mean, good for you, I wasn't sure what to say","That's... that's wonderful, I'm glad","Whew, alright, I had a bad feeling, but I'm glad I was wrong!","Great... great, I'm just, I'm checking on everyone, it helps me!","You sound honest, I'll believe you","Glad to hear it, glad to hear anything good lately!","Ohhh, wow, okay, I'm relieved, honestly","Alright... alright, I'll STOP fussing, I'm sorry","Thank goodness, I was bracing for the worst","Y-yeah? Okay, you look pretty rough, but okay","Great, then, um, what brings you here?","Y-you're okay... thank God you're okay","Oh, that's good to hear, honestly, you have no idea how rare that is","Really? You're doing okay? That makes me feel a little better","Good, I'm glad, one of us should be","Then you're ahead of me, I'm barely hanging on, but I'm glad for you"}},
{"NPC_OPEN","reg=civilian,family,worker,rescue|tmp=seasoned|st=friendly,neutral",{"Good, I figured you looked solid","Alright, glad to hear it","Fine, then, just checking","Good, that's what I like to hear","Okay, I'll leave you be","Right, no worries, just being neighborly","Good to know, good to know","That's a relief, one less thing to handle","Alright, carry on, then","Glad you're alright... stay that way","Then that's all I needed","Okay, I'll take your word for it","Good, hope it stays that way","Fine, fine, I won't pry","Okay, I'm satisfied, mostly","Good, that's one less thing to worry about","Glad to hear it, keep it up, whatever you're doing","That's better than most, take the win","Good, then we can talk like normal people for a minute"}},
{"NPC_OPEN","reg=civilian,family,worker,rescue|st=friendly",{"Oh, I'm so glad, I worry about you, you know","Yes? Wonderful, that makes my day","Good, good, you're a tough one, aren't you?!","Aw, you had me worried, silly","That's the best news I've heard all morning","I'm so pleased -- truly pleased"}},
{"NPC_OPEN","reg=civilian,family,worker,rescue|st=careful",{"Fine, then say what you came to say","Fine, so what do you want?","Alright, but I'm still watching","Then keep it that way"}},
{"NPC_OPEN","reg=civilian,family,worker,rescue|st=careful,neutral",{"So you're fine, good, stay that way, and stay over there","Good for you, now what do you want?"}},
{"NPC_OPEN","reg=family|st=friendly,neutral",{"Bless you, dear, that's wonderful, come sit"}},
{"NPC_OPEN","reg=law,swat|st=friendly,neutral",{"Glad to hear it, carry on"}},
{"NPC_OPEN","reg=law,swat|st=careful,neutral",{"Good, then you won't need anything from me"}},
{"NPC_OPEN","reg=military,elite|st=friendly,neutral",{"Understood, glad you're operational"}},
{"NPC_OPEN","reg=military,elite|st=careful,neutral",{"Good, then move along"}},
{"NPC_OPEN","reg=outlaw,raider,gang,club,crime,prison|st=friendly,neutral",{"Ha, good for you, kid, not many say that"}},
{"NPC_OPEN","reg=outlaw,raider,gang,club,crime,prison|st=careful,hostile",{"Great, then you don't need anything from me"}},
{"NPC_OPEN","",{"Good, I mean... as good as anybody gets right now - what's on your mind?","Alright, keep it that way - something you wanted to ask?","Glad to hear it, been a while since somebody said yes to that","Yeah? Good, sorry for staring, still getting used to people walking up","Then you've got one up on me - go on, I'm listening","We can talk a minute, just keep listening for trouble","Good, sit down anyway - you can be fine sitting down","Fine, I'll quit fussing at you, what'd you want to ask me?","That's the right answer whether it's true or not - go on","Huh - alright, most folks say that with their hands going","We'll talk like people a minute then... God, that's nice","Fine, then I'll ask you a favor instead of the other way round","Glad somebody is - go ahead - I'm listening","Yeah? Well, somebody in this county ought to be"}},
{"NPC_OPEN","world=road",{"Then you're doing better than this whole road - say what you came to say"}},
{"NPC_OPEN","world=fence",{"Fine, keep it short, I've got a fence to watch"}},
{"PLAYER_BITTEN","reg=civilian,family,worker,rescue|tmp=fresh|st=friendly,neutral",{"Oh God, oh God, I knew it, I knew it, I'm so sorry","Please don't come closer, I'm sorry, I'm so sorry"}},
{"PLAYER_BITTEN","reg=civilian,family,worker,rescue|tmp=seasoned|st=friendly,neutral",{"Damn, I'm sorry, that's the worst news, how do you want to handle it?","Thanks for telling me, that took guts"}},
{"PLAYER_BITTEN","reg=family|st=friendly,neutral",{"Sweet child, come here, we'll stay with you"}},
{"PLAYER_BITTEN","reg=law,swat|st=friendly,neutral",{"Stay back, we need to talk about options"}},
{"PLAYER_BITTEN","reg=military,elite|st=friendly,neutral",{"Maintain distance, we'll assess"}},
{"PLAYER_BITTEN","reg=outlaw,raider,gang,club,crime,prison|st=friendly,neutral",{"Shit, kid, I'm sorry, want a last drink?"}},
{"PLAYER_BITTEN","",{"That's... yeah, that's a bite, and I'm not going to lie to you about it","Alright, I'm looking - how long ago? The clock's the only thing that matters now","Then I'll sit right here, I ain't leaving and I ain't going to talk your ear off","I need a name, and somebody who should hear it from me","Sit down, drink this slow, and tell me about somebody you liked"}},
{"PLAYER_BITTEN","world=fence",{"That's torn, not bit, could be a nail, could be a fence - don't write yourself off yet"}},
{"PLAYER_BITTEN","world=road",{"Then let's get you off this road at least, nobody ought to do it standing up"}},
{"SHARE_FOOD","reg=civilian,family,worker,rescue|tmp=fresh|st=friendly,neutral",{"O-oh, thank you, thank you, we haven't had a decent meal in days","You'd share? With me? Oh... I could cry!","Yes? Okay, okay, I'm starving, I won't lie, I'm starving!","That's so generous, I don't know what to say","Oh, this is a gift, a real gift","Okay, good, I'll be quick, I'll be careful, I won't take more than my share","You have a kind heart, you know that?","Thank you, truly, I'll make it up to you","Oh, that smells wonderful, I mean, I imagine it does","God, I'm grateful, I really am","This is the nicest thing, honestly","I'd hug you, but my hands are shaking","Wow, thank you, you didn't have to","I promise I won't forget this","Yes, please, I'm so hungry I could cry","You mean it? For real? I could cry, I haven't had a bite since morning","Thank you!! Thank you, thank you, you have no idea","Oh my God, yes, yes please, I'm so hungry I could eat the can","Oh thank you, thank you, I haven't eaten since yesterday, you have no idea","Really? Okay... okay, yes, please, God, yes, I'm starving","You're an angel, you really are, thank you"}},
{"SHARE_FOOD","reg=civilian,family,worker,rescue|tmp=seasoned|st=friendly,neutral",{"Good... there's enough for both of us, just","Alright, let's eat, and be quick about it","Half and half, deal","Sit, eat, don't talk with your mouth full","I'm glad you said yes, I hate eating alone...","Splendid, nothing like a shared meal","Thank you... I'll return the favor...","That's neighborly, thanks","Mm, okay, it isn't much, but it's honest","Dig in, there's no ceremony here","We'll make it last..","Then we eat, and we're friends","All right... all right, pass the bread..","Pleased to share... pleased to have the company..","Good, let's not waste it","Hell, yes, don't mind if I do, appreciate it","Thanks, I'll chew slow and savor it","Alright, deal, I owe you one, a big one","Hell yes, I'll take it, thanks, saves me from another night of crackers","Thanks, I'll split it with whoever's around","Much appreciated, I owe you one"}},
{"SHARE_FOOD","reg=civilian,family,worker,rescue|st=friendly",{"Oh, I'm so happy, come, sit, there's plenty!","Eat -- eat, you're thin as a rail!!","Wonderful, I love feeding people","This is a feast, with you here","Thank you, thank you, it's a joy"}},
{"SHARE_FOOD","reg=civilian,family,worker,rescue|st=careful",{"Fine, but keep your hands where I can see them","Okay, but I'm watching how much you take","Alright, a bite, no more","We'll share, but don't think we're friends"}},
{"SHARE_FOOD","reg=civilian,family,worker,rescue|st=careful,neutral",{"Fine, but I'm eating it over here, away from you","Thanks, and no funny business"}},
{"SHARE_FOOD","reg=family|st=friendly,neutral",{"Oh dear, you've no idea what this means, thank you","Oh bless you, the kids are gonna be over the moon"}},
{"SHARE_FOOD","reg=law,swat|st=friendly,neutral",{"Thank you kindly, I'll remember this","Thanks, I'll gladly accept, it's been a long shift"}},
{"SHARE_FOOD","reg=military,elite|st=friendly,neutral",{"Grateful, thank you","Thank you, appreciated"}},
{"SHARE_FOOD","reg=outlaw,raider,gang,club,crime,prison|st=friendly,neutral",{"Aw, you're a sweetheart, I'll take it","Ha, free food, I could kiss you, I won't, but I could","Ha, don't mind if I do, you're alright","Free food? Heck yes, thanks"}},
{"SHARE_FOOD","reg=civilian,family|st=friendly,neutral|world=vehicle",{"Sit on the tailgate, I'll open it with my pocketknife, the can opener stayed with the house"}},
{"SHARE_FOOD","reg=civilian|tmp=fresh",{"Good, eating by myself has been the worst part - worse than the beans, even"}},
{"SHARE_FOOD","reg=civilian,family|tmp=fresh,seasoned|st=friendly",{"Here's a fork, it's clean, I licked it - kidding - mostly"}},
{"SHARE_FOOD","reg=family|st=friendly",{"My husband used to say a meal ain't a meal with less than two at the table - pull up that bucket"}},
{"SHARE_FOOD","reg=family|tmp=fresh|st=friendly",{"Kids, scoot over, make room for the nice stranger"}},
{"SHARE_FOOD","reg=civilian,worker|tmp=seasoned",{"Alright, half is half - I'm watching the spoon"}},
{"SHARE_FOOD","reg=worker,rescue,law|tmp=seasoned,veteran|world=road",{"Sit where you can see the road, we eat with our eyes up"}},
{"SHARE_FOOD","reg=rescue|role=rescue_clergy",{"Bless this food and the hands that found it - amen - dig in"}},
{"SHARE_FOOD","reg=rescue|role=rescue_medical,rescue_firefighter",{"Small bites, your stomach's shrunk, you'll bring it right back up"}},
{"SHARE_FOOD","reg=rescue|role=rescue_firefighter",{"Coffee's burnt and the crackers are stale, welcome to the fire department"}},
{"SHARE_FOOD","reg=law",{"Alright, {sir}, eat it here, where I can see you - no offense meant"}},
{"SHARE_FOOD","reg=military,swat",{"Good copy, eat fast, we're moving in ten"}},
{"SHARE_FOOD","reg=raider,prison|tmp=predator",{"Ha! You said it, there ain't no jerky, sucker - hungry and dumb"}},
{"SHARE_FOOD","reg=raider,gang,prison|tmp=predator",{"Look at him, begging for a stick of jerky - fine - catch, now crawl for it"}},
{"SHARE_FOOD","reg=civilian,worker|st=friendly",{"Pull up a cinderblock, nobody eats alone out here unless they're a jerk"}},
{"SHARE_FOOD","reg=family,civilian|tmp=fresh,seasoned|st=friendly",{"Okay, my daughter would've liked you - she fed every stray on Hilltop Road"}},
{"SHARE_FOOD","reg=civilian,worker,outlaw|tmp=seasoned",{"Tastes like the can, everything tastes like the can now"}},
{"SHARE_FOOD","reg=outlaw,crime",{"Alright, you earned it by asking straight - eat, then get gone"}},
{"SHARE_FOOD","reg=civilian,family,worker|st=friendly,neutral",{"Eat, nobody talks about how bad it is while there's food in front of us - that's the rule"}},
{"SHARE_FOOD","reg=elite,military|tmp=veteran",{"Roger, share line's two feet apart - don't reach across me"}},
}
